use Illuminate\Validation\ValidationException;
class DailyWord {
 // Keep order stable: each UTC calendar day advances one position.
 private const WORDS = 'REALM STAMP PEACH SLICE SHAPE PEARL ALERT SWEAR FATAL BEGIN HARDY CAMEL LEVEL CHOIR CHIEF WHOLE COAST LAYER AMONG STRAP SCARF LUNCH TROOP TOUGH THIRD HORSE CRAFT ARISE STUDY NOTCH FLOAT CANDY CRAZY ALLOW KNOWN SHARE PLUCK INNER CREEK SHALL STRIP TRACE ALARM MIGHT PRICE FAULT SPRAY NEWER PLEAD FLOUR CRUDE CRUSH RIGHT THEME FIFTH YIELD SORRY FAIRY FLEET TRUCK SOLID ELECT BEACH BRAVE FIRST SLOPE GRAIN FAINT GRILL BLOCK EAGER KNIFE CHECK LINEN MANGO GRIEF UTTER PHOTO ABOUT MODEL FIGHT PASTA PLACE SMALL OLIVE SCOPE SPOKE METAL BRUSH CARRY CURVE GLOBE CHINA MAYOR LEMON SWEAT THICK CHAIR DRAFT MATCH NIGHT VITAL FUNNY ROUND STICK DEATH MOTOR QUITE PLANE ANGER ALIKE BLEND SCRAP SOLVE WEAVE AGILE FALSE SERVE SLIDE DIARY GREEN STACK DIRTY GRASS SHOUT VALUE PINCH BEARD SCALE CLOTH WEDGE MERCY ANGLE SUNNY BLAZE INPUT PHONE SOLAR SENSE PUPIL SHARK DEALT STEAM ASIDE UPPER FIFTY SURGE DREAM INDEX CLOSE LOWER RIVER USAGE GUILD SCOUT TWICE FERRY PAINT GROSS ARGUE BLADE SMART SCARE SNAKE PRIOR RANCH GOING GREET YACHT BLANK PULSE TEACH WEIGH EARTH THROW WRITE FLUTE OWNER VIVID LIGHT SPACE SWAMP DRAIN MEDIA TRADE COULD NASTY FOUND TWIST REPLY SWORD TRIED CLIFF MERGE BASIC PRIDE QUIET BIRTH DRESS GRANT LOOSE SUGAR BEAST WATCH DEPTH LEASE FOCUS SOUND PRIZE IMPLY IRONY TREND COMET QUERY BREAK KNOCK SPEAK FLOOD GIANT CHESS ROUGH BERRY PLAIN SWIFT MAJOR FRESH UNITY BUILT BUNCH FORTY URBAN BRAND MONTH SLEEP ALIGN GLIDE EVERY STARE JOKER SCENE POINT SKILL SEVEN CHASE FLOOR OTTER FRONT TIGER GLORY PRESS DROVE PANEL CHUNK GRADE WHERE AMBER GRACE ADULT MUSIC RAISE AWAIT COUNT PHASE CHEST CHAIN CLEAN CHOSE FANCY FORTH GRAPH ALONE SPOON SALAD NEWLY TRUST SWEET ELDER FETCH BROKE TRAIT CABIN FORUM RELAY QUEST EXIST SHADE TRIBE YEARN POUND TRICK DIGIT ROUTE HONEY APPLY TRAIL RENEW ROYAL WHEAT PEACE BAKER FORCE FLUID STOCK MONEY TRIAL JUICY CANOE ALIVE HEAVY RINSE GLOVE STEER DAILY FIERY FAVOR YOUNG NOISE PILOT LEAST CLIMB CABLE SIXTH QUEEN JOLLY TEETH VALID FORGE VOICE DINER OTHER BROAD CHARM STEMS JOINT TIRED CLOWN NEVER CLASH APART PIECE PLANT OUTER FIXED GROUP ALBUM THOSE FRAME CREAM SHEEP SPEND PAPER REFER TOWER SMILE ONION TITLE EARLY TRACK AWAKE PARTY MEDAL PENNY ACUTE VIDEO WOUND MARRY ORDER SHORT EMPTY SKIRT GLASS SLATE ELBOW THINK LASER TOUCH RAPID PLATE MINOR SWING SALTY SPARE RIGID USUAL BOARD GRAVE BONUS SHARP DRAWN FRUIT MAPLE POLAR WHITE GRASP GRAPE THIEF STALE LIMIT HONOR SMELL BROWN ROCKY HEART CRISP WATER TOOTH EVENT VIRAL ACTOR HEDGE EXACT GUEST QUICK WIDTH OXIDE CYCLE LOGIC TABLE CLASS UNTIL DRINK CRAWL STORE ALTER GLEAM UNITE NYLON EIGHT YEAST COACH WORSE NERVE LEAVE BOUND COUCH MOUNT RADIO CLAIM BADGE PROVE ELITE CROWN LUCKY AFTER CLOUD GHOST BRIDE UNDER ANGEL PITCH THERE GRIND CATCH REBEL IMAGE WOMEN YOUTH STYLE COVER MOUSE STAIN NURSE LYRIC WEARY PATCH CHILD FIELD WAGON PROOF BRICK BENCH RALLY ENJOY MAGIC BELOW TIGHT STAKE FLASH JELLY TAKEN AGAIN BOOTH OCEAN TRULY SCENT SCORE AGREE BRAIN THEFT CROSS DELAY WORLD LOYAL ROBIN HENCE RUGBY PIANO DOUBT WORRY LARGE THREE TOKEN TOPIC SIGHT SADLY EQUAL STAFF GUARD SOUTH LEARN GUIDE ENEMY ENTER COURT ERROR RURAL DRIVE WRONG BLIND SHELF FEVER PAUSE SHIFT JUICE STUFF SPORT WOMAN CARVE SHORE DRANK AWARE HASTE STAIR WHICH ORBIT RESET CHILL WROTE SPILL LATER BLACK OUGHT APPLE TASTE SHIRT CHALK SMOKE ADMIT TIMER STAGE SPARK BLOOM LOCAL MORAL CRACK HUMOR ALIEN ARENA FEWER SKULL CHEAP RATIO MARCH HOUSE HELLO PIZZA PLAZA STILL QUOTE THREW VAPOR CAUSE OFFER STRAW ROBOT REACT STAND BLAME ZESTY READY LEGAL SUPER LODGE CRANE WORST STONE WHOSE GREAT JUDGE ADOPT FLAME POWER NINTH TODAY GIVEN ISSUE RIDGE SHEER ARMOR MOUTH ABOVE LOVER UPSET THUMB DRILL TORCH FEAST SHAME MAKER CHEEK SINCE SPINE CLOCK RANGE STEEL START STORY TRUTH CLERK ASSET VOTER SPICE BOAST CROWD CORAL HUMAN LABOR STORM THANK OPERA SHAKE IDEAL VOCAL BOOST BLESS DANCE THING SPEED ANGRY TOTAL CLICK TRAIN ROAST DRIED FLESH BLAST DOUGH STOOD SHINE BRIEF IVORY TREAT FAITH RELAX THEIR BREED AVOID SILLY SHOCK BASIL VISIT FENCE OFTEN BREAD WOULD DRIFT AHEAD MAYBE BUILD WORTH STOVE STATE NOBLE AUDIO SHEET SPELL NOVEL AWARD QUILT FINAL WEIRD CLEAR FIBER NORTH WHALE LAUGH THESE HABIT SUITE DRAMA AROMA SAUCE STEEP FROST CRASH UNION SHELL WHILE GUESS SNAIL PRIME AGENT WHEEL REACH PROUD MELON EXTRA HAPPY ALONG COCOA ORGAN LIVER ENTRY GROWN HOTEL PANIC MOVIE WASTE BURST NAIVE BRING ZEBRA GRAND LABEL PRINT';
 public static function date(): string { return now('UTC')->toDateString(); }
 public static function calendar(): array { return ['date'=>self::date(),'resets_at'=>now('UTC')->addDay()->startOfDay()->toIso8601String(),'timezone'=>'UTC']; }
 public static function answer(string $date): string {
  $words=explode(' ',self::WORDS); $day=(int)floor(strtotime($date.' UTC')/86400);
  return $words[$day % count($words)];
 }
 public static function start(): array { return ['date'=>self::date(),'guesses'=>[],'status'=>'playing']; }
 public static function score(string $answer,string $guess): array {
  $colors=array_fill(0,5,'absent');$remaining=[];
  for($i=0;$i<5;$i++) { if($guess[$i]===$answer[$i])$colors[$i]='correct';else $remaining[$answer[$i]]=($remaining[$answer[$i]]??0)+1; }
  for($i=0;$i<5;$i++) if($colors[$i]!=='correct'&&($remaining[$guess[$i]]??0)>0){$colors[$i]='present';$remaining[$guess[$i]]--;}
  return $colors;
 }
 public static function guess(array $s,string $guess): array {
  if(!in_array($guess,explode(' ',self::WORDS),true))throw ValidationException::withMessages(['word'=>'That word is not in our word list. Try another five-letter word.']);
  $answer=self::answer($s['date']);$s['guesses'][]=['word'=>$guess,'colors'=>self::score($answer,$guess)];
  if($guess===$answer)$s['status']='won';elseif(count($s['guesses'])===6)$s['status']='lost';return $s;
 }
 public static function view(array $s): array { if($s['status']!=='playing')$s['answer']=self::answer($s['date']);return $s; }
}
